import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        if (n == -1) return;

        int[] head = new int[n + 1];
        int[] to = new int[2 * m + 2];
        int[] next = new int[2 * m + 2];
        int edgeCount = 0;

        int[] deg = new int[n + 1];

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();

            edgeCount++;
            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount;

            edgeCount++;
            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount;

            deg[u]++;
            deg[v]++;
        }

        boolean[] visited = new boolean[n + 1];
        int[] queue = new int[n + 1];
        ArrayList<Integer> comp = new ArrayList<>();
        boolean[] isNeighbor = new boolean[n + 1];

        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                comp.clear();
                int qHead = 0, qTail = 0;
                queue[qTail++] = i;
                visited[i] = true;

                long sumDeg = 0;

                while (qHead < qTail) {
                    int u = queue[qHead++];
                    comp.add(u);
                    sumDeg += deg[u];

                    for (int e = head[u]; e != 0; e = next[e]) {
                        int v = to[e];
                        if (!visited[v]) {
                            visited[v] = true;
                            queue[qTail++] = v;
                        }
                    }
                }

                long vCount = comp.size();
                long eCount = sumDeg / 2;

                if (eCount < vCount * (vCount - 1) / 2) {
                    int targetU = -1;
                    for (int u : comp) {
                        if (deg[u] < vCount - 1) {
                            targetU = u;
                            break;
                        }
                    }

                    isNeighbor[targetU] = true;
                    for (int e = head[targetU]; e != 0; e = next[e]) {
                        isNeighbor[to[e]] = true;
                    }

                    int targetV = -1;
                    for (int v : comp) {
                        if (!isNeighbor[v]) {
                            targetV = v;
                            break;
                        }
                    }

                    System.out.println(targetU + " " + targetV);
                    return;
                }
            }
        }

        System.out.println(-1);
    }
}
